UPDATE `sliders` SET `title_fr` = 'Bienvenue à la Direction des Œuvres Universitaires de Sétif', `title_en` = 'Welcome to the Directorate of University Services of Sétif', `subtitle_fr` = 'Au service de l''étudiant : hébergement, restauration, transport et bourses', `subtitle_en` = 'Serving students: accommodation, catering, transport and scholarships' WHERE `order` = 1;
