UPDATE `director_words` SET `director_name_fr` = 'Mohamed El Amine Benali', `director_name_en` = 'Mohamed El Amine Benali', `director_title_fr` = 'Directeur des Œuvres Universitaires', `director_title_en` = 'Director of University Services', `word_title_fr` = 'Mot du directeur', `word_title_en` = 'Director''s message', `word_content_fr` = 'Au nom de Dieu, le Clément, le Miséricordieux\n\nJ''ai le plaisir de vous souhaiter la bienvenue sur le site officiel de la Direction des Œuvres Universitaires de la wilaya de Sétif, une fenêtre que nous voulons être un pont de communication entre la Direction et nos chers étudiants.\n\nLa Direction veille à offrir les meilleures conditions d''hébergement, de restauration, de transport et de bourses à des milliers d''étudiants. Elle s''efforce sans cesse d''améliorer ses services et de les rapprocher de l''étudiant grâce à la numérisation, notamment avec l''espace étudiant qui vous permet de déposer et de suivre vos demandes depuis chez vous.\n\nNos portes restent ouvertes à toute suggestion ou remarque. Nous vous souhaitons une excellente année universitaire.', `word_content_en` = 'In the name of God, the Most Gracious, the Most Merciful\n\nI am pleased to welcome you to the official website of the Directorate of University Services of the Wilaya of Sétif, a window we want to be a bridge of communication between the Directorate and our dear students.\n\nThe Directorate strives to provide the best accommodation, catering, transport and scholarship conditions to thousands of students. It constantly works to improve its services and bring them closer to students through digitalization, including the student area that allows you to submit and track your applications from home.\n\nOur doors are open to any suggestion or remark. We wish you a successful academic year.' WHERE id = 1;
UPDATE `organization_structures` SET `title_fr` = 'Organigramme', `title_en` = 'Organizational structure', `description_fr` = 'La Direction se compose d''un directeur dont relèvent quatre services principaux, ainsi que de bureaux de coordination avec les résidences universitaires.', `description_en` = 'The Directorate consists of a director supervising four main departments, along with offices coordinating with the university residences.', `content_fr` = 'Les quatre services (bourses, hébergement, restauration, transport) travaillent sous l''autorité directe du directeur et se coordonnent avec les directeurs des résidences universitaires pour assurer le bon déroulement des services quotidiens aux étudiants.', `content_en` = 'The four departments (scholarships, accommodation, catering, transport) work under the direct supervision of the director and coordinate with the university residence directors to ensure the smooth running of daily services for students.' WHERE id = 1;
UPDATE `directorate_histories` SET `title_fr` = 'Historique de la Direction', `title_en` = 'History of the Directorate', `introduction_fr` = 'La Direction des Œuvres Universitaires de la wilaya de Sétif a été créée pour accompagner la forte expansion de l''université ; elle prend en charge depuis les services sociaux des étudiants.', `introduction_en` = 'The Directorate of University Services of the Wilaya of Sétif was created to keep pace with the university''s major expansion, and has since been in charge of students'' social services.', `content_fr` = 'La Direction a débuté avec une seule résidence universitaire et un seul restaurant, puis s''est progressivement développée avec la création du pôle universitaire d''El Bez. Elle compte aujourd''hui plusieurs résidences, restaurants et une flotte de transport au service de milliers d''étudiants chaque jour.\n\nCes dernières années, la Direction est entrée dans l''ère du numérique : l''étudiant peut désormais déposer et suivre ses demandes en ligne.', `content_en` = 'The Directorate started with a single university residence and a single restaurant, then gradually expanded with the creation of the El Bez university hub. Today it runs several residences, restaurants and a transport fleet serving thousands of students every day.\n\nIn recent years, the Directorate has embraced digitalization: students can now submit and track their applications online.' WHERE id = 1;
UPDATE `news` SET `title_fr` = 'Versement de la première tranche de la bourse universitaire', `title_en` = 'Payment of the first installment of the university scholarship', `summary_fr` = 'Le versement de la première tranche de la bourse universitaire a commencé au profit des étudiants bénéficiaires, sur leurs comptes postaux.', `summary_en` = 'Payment of the first installment of the university scholarship has started for eligible students, via their postal accounts.', `content_fr` = 'La Direction des Œuvres Universitaires de la wilaya de Sétif informe l''ensemble des étudiants boursiers du lancement du versement de la première tranche de la bourse universitaire. Le montant peut être retiré du compte courant postal à partir de dimanche.\n\nPour toute information, veuillez vous rapprocher du service des bourses.', `content_en` = 'The Directorate of University Services of the Wilaya of Sétif informs all scholarship students that payment of the first installment of the university scholarship has started. The amount can be withdrawn from the postal current account starting Sunday.\n\nFor any inquiries, please contact the scholarship department.' WHERE slug = 'sarf-al-minha';
UPDATE `news` SET `title_fr` = 'Inauguration d''une nouvelle bibliothèque à la résidence universitaire Debaghine', `title_en` = 'A new library opens at the Debaghine university residence', `summary_fr` = 'Une nouvelle bibliothèque équipée d''une salle de lecture de cent vingt places a été inaugurée.', `summary_en` = 'A new library with a reading room for one hundred and twenty students has been inaugurated.', `content_fr` = 'Dans le cadre de l''amélioration des conditions de révision, une nouvelle bibliothèque a été inaugurée à la résidence universitaire Debaghine. Elle dispose d''une salle de lecture de cent vingt places et de plus de trois mille titres.', `content_en` = 'As part of efforts to improve study conditions, a new library has been inaugurated at the Debaghine university residence. It features a reading room for one hundred and twenty students and more than three thousand titles.' WHERE slug = 'maktaba-jadida';
UPDATE `news` SET `title_fr` = 'Renforcement des lignes de transport vers le pôle universitaire d''El Bez', `title_en` = 'More university transport lines to the El Bez university hub', `summary_fr` = 'De nouveaux bus ont été ajoutés pour réduire l''attente aux heures de pointe.', `summary_en` = 'New buses have been added to reduce waiting times at peak hours.', `content_fr` = 'Afin de renforcer le service de transport universitaire, de nouveaux bus ont été ajoutés sur les lignes desservant le pôle universitaire d''El Bez pour réduire le temps d''attente aux heures de pointe.', `content_en` = 'To strengthen the university transport service, new buses have been added to the lines serving the El Bez university hub in order to reduce waiting times at peak hours.' WHERE slug = 'naql-jamii';
UPDATE `news` SET `title_fr` = 'Menu hebdomadaire des restaurants universitaires', `title_en` = 'Weekly menu in the university restaurants', `summary_fr` = 'Découvrez le menu proposé cette semaine dans tous les restaurants universitaires.', `summary_en` = 'Discover this week''s menu in all university restaurants.', `content_fr` = 'Le service de la restauration publie le menu hebdomadaire des restaurants universitaires, en veillant à l''équilibre nutritionnel et à la variété des plats.', `content_en` = 'The catering department publishes the weekly menu of the university restaurants, with attention to nutritional balance and a variety of dishes.' WHERE slug = 'qaimat-al-wajabat';
UPDATE `news` SET `title_fr` = 'Ouverture des inscriptions aux résidences universitaires pour l''année 2026/2027', `title_en` = 'Registration for university residences opens for 2026/2027', `summary_fr` = 'Les nouveaux et anciens étudiants peuvent déposer leurs demandes d''hébergement via l''espace étudiant.', `summary_en` = 'New and returning students can submit their accommodation applications through the student area.', `content_fr` = 'La Direction annonce l''ouverture des inscriptions aux résidences universitaires pour l''année 2026/2027. L''étudiant dépose sa demande via l''espace étudiant, accompagnée des pièces requises.', `content_en` = 'The Directorate announces that registration for university residences for the 2026/2027 academic year is now open. Students submit their application through the student area, along with the required documents.' WHERE slug = 'tasjilat-al-iqamat';
