UPDATE `activities` SET `title_fr` = 'Tournoi de football inter-résidences universitaires', `title_en` = 'Inter-residence university football tournament', `short_description_fr` = 'Un tournoi sportif réunissant les équipes des résidences universitaires de la wilaya de Sétif dans une ambiance fraternelle, avec plus de vingt équipes.', `short_description_en` = 'A sports tournament bringing together teams from the university residences of the Wilaya of Sétif in a friendly atmosphere, with more than twenty teams.', `description_fr` = 'Un tournoi sportif réunissant les équipes des résidences universitaires de la wilaya de Sétif dans une ambiance fraternelle, avec plus de vingt équipes.\n\nLa Direction organise cette activité dans le cadre de son programme culturel et sportif annuel au profit des étudiants résidents.', `description_en` = 'A sports tournament bringing together teams from the university residences of the Wilaya of Sétif in a friendly atmosphere, with more than twenty teams.\n\nThe Directorate organizes this activity as part of its annual cultural and sports program for resident students.', `location_fr` = 'Stade universitaire d''El Bez', `location_en` = 'El Bez university stadium', `organizer_fr` = 'Direction des Œuvres Universitaires', `organizer_en` = 'Directorate of University Services' WHERE slug = 'dawrat-korat-al-qadam';
UPDATE `activities` SET `title_fr` = 'Soirée poétique à l''occasion de la Journée de l''étudiant', `title_en` = 'Poetry evening for Student Day', `short_description_fr` = 'Une soirée littéraire où les étudiants déclament leurs poèmes et concourent pour le prix du meilleur poème.', `short_description_en` = 'A literary evening where students recite their poems and compete for the best poem award.', `description_fr` = 'Une soirée littéraire où les étudiants déclament leurs poèmes et concourent pour le prix du meilleur poème.\n\nLa Direction organise cette activité dans le cadre de son programme culturel et sportif annuel au profit des étudiants résidents.', `description_en` = 'A literary evening where students recite their poems and compete for the best poem award.\n\nThe Directorate organizes this activity as part of its annual cultural and sports program for resident students.', `location_fr` = 'Salle de conférences, résidence Debaghine', `location_en` = 'Lecture hall, Debaghine residence', `organizer_fr` = 'Direction des Œuvres Universitaires', `organizer_en` = 'Directorate of University Services' WHERE slug = 'umsiya-shiriya';
UPDATE `activities` SET `title_fr` = 'Salon du livre universitaire', `title_en` = 'University book fair', `short_description_fr` = 'Un salon proposant des milliers de titres dans toutes les spécialités, à prix réduits pour les étudiants.', `short_description_en` = 'A fair offering thousands of titles in all fields at reduced prices for students.', `description_fr` = 'Un salon proposant des milliers de titres dans toutes les spécialités, à prix réduits pour les étudiants.\n\nLa Direction organise cette activité dans le cadre de son programme culturel et sportif annuel au profit des étudiants résidents.', `description_en` = 'A fair offering thousands of titles in all fields at reduced prices for students.\n\nThe Directorate organizes this activity as part of its annual cultural and sports program for resident students.', `location_fr` = 'Bibliothèque centrale', `location_en` = 'Central library', `organizer_fr` = 'Direction des Œuvres Universitaires', `organizer_en` = 'Directorate of University Services' WHERE slug = 'maarad-al-kitab';
