UPDATE `services` SET `title_fr` = 'Transport universitaire', `title_en` = 'University transport', `short_description_fr` = 'Transport quotidien gratuit des étudiants entre les résidences et les pôles universitaires grâce à un réseau de lignes régulières.', `short_description_en` = 'Free daily transport for students between residences and university hubs through a network of regular lines.', `detailed_description_fr` = 'Transport quotidien gratuit des étudiants entre les résidences et les pôles universitaires grâce à un réseau de lignes régulières.\n\nCe service est assuré par le service compétent de la Direction.', `detailed_description_en` = 'Free daily transport for students between residences and university hubs through a network of regular lines.\n\nThis service is managed by the relevant department of the Directorate.', `requirements_fr` = 'Carte d''étudiant\nCertificat de scolarité\nPhoto d''identité', `requirements_en` = 'Student card\nCertificate of enrollment\nPassport photo', `how_to_apply_fr` = 'La demande est déposée via l''espace étudiant du site ; les dossiers sont ensuite étudiés et les résultats annoncés.', `how_to_apply_en` = 'Applications are submitted through the student area of the website; files are then reviewed and the results announced.', `contact_info_fr` = 'Téléphone : 036 00 00 10', `contact_info_en` = 'Phone: 036 00 00 10' WHERE slug = 'naql-jamii';
