UPDATE `faqs` SET `question_fr` = 'Qu''est-ce que la Direction des Œuvres Universitaires ?', `question_en` = 'What is the Directorate of University Services?', `answer_fr` = 'Un établissement public chargé des services sociaux des étudiants universitaires : hébergement, restauration, transport, bourses et activités culturelles et sportives.', `answer_en` = 'A public institution in charge of university students'' social services: accommodation, catering, transport, scholarships and cultural and sports activities.' WHERE `order` = 1;
UPDATE `faqs` SET `question_fr` = 'Comment contacter la Direction ?', `question_en` = 'How can I contact the Directorate?', `answer_fr` = 'Via la page « Contactez-nous » du site, ou en vous présentant au siège de la Direction pendant les heures de travail.', `answer_en` = 'Through the "Contact us" page of the website, or by visiting the Directorate''s headquarters during working hours.' WHERE `order` = 2;
UPDATE `faqs` SET `question_fr` = 'Comment obtenir la bourse universitaire ?', `question_en` = 'How do I get the university scholarship?', `answer_fr` = 'En déposant une demande de bourse via l''espace étudiant, accompagnée d''une attestation de revenu familial dans les délais fixés, puis en suivant l''état de la demande.', `answer_en` = 'By submitting a scholarship application through the student area, together with a family income certificate within the set deadlines, and then tracking the status of the application.' WHERE `order` = 3;
UPDATE `faqs` SET `question_fr` = 'Quand la bourse est-elle versée ?', `question_en` = 'When is the scholarship paid?', `answer_fr` = 'La bourse est versée en trois tranches au cours de l''année universitaire ; chaque tranche est annoncée dans la rubrique Actualités.', `answer_en` = 'The scholarship is paid in three installments during the academic year; each installment is announced in the News section.' WHERE `order` = 4;
UPDATE `faqs` SET `question_fr` = 'Quelles sont les conditions pour bénéficier d''un logement universitaire ?', `question_en` = 'What are the conditions for university housing?', `answer_fr` = 'Être inscrit à l''université et résider à une certaine distance de son établissement, la priorité étant accordée selon l''éloignement et la situation sociale.', `answer_en` = 'Students must be enrolled at the university and live a certain distance from their institution, with priority given according to distance and social situation.' WHERE `order` = 5;
UPDATE `faqs` SET `question_fr` = 'Puis-je changer de résidence ?', `question_en` = 'Can I change residence?', `answer_fr` = 'Oui, en déposant une demande de transfert auprès du service de l''hébergement ; elle est étudiée selon les places disponibles.', `answer_en` = 'Yes, by submitting a transfer request to the accommodation department; it is reviewed according to the places available.' WHERE `order` = 6;
UPDATE `application_types` SET `name_fr` = 'Demande de bourse universitaire', `name_en` = 'University scholarship application', `description_fr` = 'Demande d''obtention de la bourse d''études', `description_en` = 'Application for a study grant', `required_documents_fr` = 'Attestation de revenu', `required_documents_en` = 'Income certificate' WHERE `order` = 1;
UPDATE `application_types` SET `name_fr` = 'Demande de logement universitaire', `name_en` = 'University housing application', `description_fr` = 'Demande de bénéficier d''un logement universitaire', `description_en` = 'Application for university housing', `required_documents_fr` = 'Certificat de résidence', `required_documents_en` = 'Certificate of residence' WHERE `order` = 2;
UPDATE `student_notifications` SET `title_fr` = 'Votre demande a été reçue', `title_en` = 'Your application has been received', `message_fr` = 'Votre demande n° 202600007 (Demande de bourse universitaire) a été reçue ; elle est en attente.', `message_en` = 'Your application no. 202600007 (University scholarship application) has been received and is pending.' WHERE title = 'تم استلام طلبك';
UPDATE `student_notifications` SET `title_fr` = 'Votre demande a été approuvée ✅', `title_en` = 'Your application has been approved ✅', `message_fr` = 'Votre demande n° 202600011 (Demande de logement universitaire) a été approuvée.', `message_en` = 'Your application no. 202600011 (University housing application) has been approved.' WHERE title = 'تم اعتماد طلبك ✅';
UPDATE `student_notifications` SET `title_fr` = 'Bienvenue dans l''espace étudiant', `title_en` = 'Welcome to the student area', `message_fr` = 'Vous pouvez désormais déposer et suivre vos demandes depuis votre compte.', `message_en` = 'You can now submit and track your applications from your account.' WHERE title = 'مرحباً بك في فضاء الطالب';
